 c=g['coordinates']; ps=[c] if g['type']=='Polygon' else c; pts=[pt for poly in ps for ring in poly for pt in ring]
 return {'type':g['type'],'components':len(ps),'rings':sum(len(x) for x in ps),'interior_rings':sum(max(0,len(x)-1) for x in ps),'vertices':sum(len(r) for p in ps for r in p),'bbox':[min(p[0] for p in pts),min(p[1] for p in pts),max(p[0] for p in pts),max(p[1] for p in pts)]}
